/* ---------------- helpers ---------------- */
function publicUser(u) {
  return { id: u.id, role: u.role, name: u.name, username: u.username,
           email: u.email, mobile: u.mobile, verified: u.verified };
}
function validEmail(e) { return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e); }
function newId() { return Date.now().toString(36) + crypto.randomBytes(4).toString('hex'); }

/* ---------------- OTP SENDING ---------------- */
async function sendOtpSms(mobile, code) {
  const res = await fetch('https://api.msg91.com/api/v5/flow', {
    method: 'POST',
    headers: { 'authkey': MSG91.authKey, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      template_id: MSG91.templateId,
      short_url: '0',
      recipients: [{ mobiles: '91' + mobile, VAR1: String(code), OTP: String(code) }]
    })
  });
  if (!res.ok) throw new Error('MSG91 error ' + res.status);
}

let mailTransporter = null;
function getMailer() {
  if (!mailTransporter) {
    mailTransporter = nodemailer.createTransport({
      host: SMTP.host, port: SMTP.port, secure: SMTP.port === 465,
      auth: { user: SMTP.user, pass: SMTP.pass }
    });
  }
  return mailTransporter;
}
async function sendOtpMail(email, code) {
  await getMailer().sendMail({
    from: SMTP.from,
    to: email,
    subject: 'Your OTP - Vishwajeet Parmar Rajput Train Ticket',
    text: 'Your OTP is ' + code + '. It is valid for 10 minutes. Do not share it with anyone.',
    html: '<div style="font-family:Arial,sans-serif;max-width:480px;margin:auto;border:1px solid #dfe3ec;border-radius:8px;padding:24px">'
      + '<h2 style="color:#1b2f6e;margin:0 0 8px">OTP Verification</h2>'
      + '<p style="color:#22293a">Your One-Time Password is:</p>'
      + '<p style="font-size:30px;font-weight:800;letter-spacing:6px;color:#f47129;margin:12px 0">' + code + '</p>'
      + '<p style="color:#6b7386;font-size:12px">Valid for 10 minutes. Do not share it with anyone.</p>'
      + '</div>'
  });
}

const OTP_TTL_MS = 10 * 60 * 1000;      /* 10 minutes */
const OTP_RESEND_MS = 60 * 1000;        /* resend allowed every 60 s */
const OTP_MAX_TRIES = 5;

async function issueOtp(user) {
  const now = Date.now();
  const existing = db.otps[user.id];
  if (existing && existing.lastSent && (now - existing.lastSent) < OTP_RESEND_MS) {
    const wait = Math.ceil((OTP_RESEND_MS - (now - existing.lastSent)) / 1000);
    return { ok: false, error: 'Please wait ' + wait + ' seconds before requesting a new OTP.' };
  }
  const code = String(100000 + Math.floor(Math.random() * 900000));
  db.otps[user.id] = {
    codeHash: bcrypt.hashSync(code, 8),
    expires: now + OTP_TTL_MS,
    tries: 0,
    lastSent: now
  };
  saveDb();

  let smsErr = null, mailErr = null;
  if (SMS_OK) { try { await sendOtpSms(user.mobile, code); } catch (e) { smsErr = e.message; } }
  if (MAIL_OK) { try { await sendOtpMail(user.email, code); } catch (e) { mailErr = e.message; } }

  if (smsErr && mailErr) return { ok: false, error: 'OTP could not be sent (SMS: ' + smsErr + ' / Email: ' + mailErr + ')' };
  return { ok: true, devCode: (OTP_DEV_MODE || (smsErr && !SMS_OK) || (mailErr && !MAIL_OK)) ? code : null };
}

