app.post('/api/register', async (req, res) => {
  const { name, username, mobile, email, password } = req.body || {};
  const uname = String(username || '').trim().toLowerCase();
  const mob = String(mobile || '').trim();
  const mail = String(email || '').trim().toLowerCase();

  if (!name || String(name).trim().length < 2) return res.status(400).json({ error: 'Please enter your full name.' });
  if (!/^[a-z0-9_]{3,20}$/.test(uname)) return res.status(400).json({ error: 'User name must be 3-20 characters (a-z, 0-9, _ only).' });
  if (!/^\d{10}$/.test(mob)) return res.status(400).json({ error: 'Mobile number must be exactly 10 digits.' });
  if (!validEmail(mail)) return res.status(400).json({ error: 'Please enter a valid email address.' });
  if (!password || String(password).length < 6) return res.status(400).json({ error: 'Password must be at least 6 characters.' });

  if (db.users.find(u => u.username === uname)) return res.status(409).json({ error: 'This user name is already taken.' });
  if (db.users.find(u => u.mobile === mob)) return res.status(409).json({ error: 'This mobile number is already registered.' });
  if (db.users.find(u => u.email === mail)) return res.status(409).json({ error: 'This email is already registered.' });

  const user = {
    id: newId(), role: 'customer', name: String(name).trim(),
    username: uname, email: mail, mobile: mob,
    passHash: bcrypt.hashSync(String(password), 10),
    verified: false, created: new Date().toISOString()
  };
  db.users.push(user);
  saveDb();

  const otp = await issueOtp(user);
  if (!otp.ok) {
    db.users = db.users.filter(u => u.id !== user.id);
    saveDb();
    return res.status(429).json({ error: otp.error });
  }
  res.json({ ok: true, message: 'OTP sent to your mobile and email. It is valid for 10 minutes.', devCode: otp.devCode });
});

app.post('/api/resend-otp', async (req, res) => {
  const uname = String((req.body || {}).username || '').trim().toLowerCase();
  const user = db.users.find(u => u.username === uname || u.email === uname || u.mobile === uname);
  if (!user) return res.status(404).json({ error: 'Account not found.' });
  if (user.verified) return res.json({ ok: true, message: 'Already verified. Please log in.' });
  const otp = await issueOtp(user);
  if (!otp.ok) return res.status(429).json({ error: otp.error });
  res.json({ ok: true, message: 'New OTP sent.', devCode: otp.devCode });
});

app.post('/api/verify-otp', (req, res) => {
  const uname = String((req.body || {}).username || '').trim().toLowerCase();
  const code = String((req.body || {}).otp || '').trim();
  const user = db.users.find(u => u.username === uname || u.email === uname || u.mobile === uname);
  if (!user) return res.status(404).json({ error: 'Account not found.' });

  const rec = db.otps[user.id];
  if (!rec) return res.status(400).json({ error: 'No OTP was requested. Please register again.' });
  if (Date.now() > rec.expires) return res.status(400).json({ error: 'OTP expired. Please request a new one.' });
  if (rec.tries >= OTP_MAX_TRIES) return res.status(429).json({ error: 'Too many wrong attempts. Please request a new OTP.' });

  if (!bcrypt.compareSync(code, rec.codeHash)) {
    rec.tries += 1; saveDb();
    return res.status(400).json({ error: 'Wrong OTP. Attempts left: ' + (OTP_MAX_TRIES - rec.tries) });
  }
  user.verified = true;
  delete db.otps[user.id];
  saveDb();

  /* auto login after verification */
  req.session.user = { id: user.id, username: user.username, role: user.role, name: user.name };
  res.json({ ok: true, message: 'Mobile and email verified successfully! You are logged in.', user: publicUser(user) });
});

app.post('/api/login', (req, res) => {
  const uname = String((req.body || {}).username || '').trim().toLowerCase();
  const password = String((req.body || {}).password || '');
  const user = db.users.find(u => u.username === uname || u.email === uname || u.mobile === uname);
  if (!user || !bcrypt.compareSync(password, user.passHash)) {
    return res.status(401).json({ error: 'Wrong user name / email / mobile or password.' });
  }
  if (!user.verified) {
    return res.status(403).json({ error: 'Your account is not verified yet. Please verify with OTP first.', needVerify: true, username: user.username });
  }
  req.session.user = { id: user.id, username: user.username, role: user.role, name: user.name };
  res.json({ ok: true, user: publicUser(user) });
});

app.post('/api/logout', (req, res) => {
  req.session.destroy(() => res.json({ ok: true }));
});

app.get('/api/me', (req, res) => {
  const u = db.users.find(x => x.id === (req.session.user || {}).id);
  if (!u) return res.status(401).json({ error: 'Not logged in.' });
  res.json({ user: publicUser(u) });
});

/* ---------------- PASSENGERS API ---------------- */
app.get('/api/passengers', requireAuth, (req, res) => {
  const mine = db.passengers.filter(p => p.userId === req.session.user.id);
  res.json({ passengers: mine });
});

app.post('/api/passengers', requireAuth, (req, res) => {
  const { name, age, gender, berth, food } = req.body || {};
  const n = String(name || '').trim();
  const a = parseInt(age, 10);
  if (!n || n.length < 2) return res.status(400).json({ error: 'Please enter the passenger name (as per ID).' });
  if (!a || a < 1 || a > 120) return res.status(400).json({ error: 'Please enter a valid age (1-120).' });
  const p = {
    id: newId(), userId: req.session.user.id,
    name: n.toUpperCase(), age: a,
    gender: ['Male', 'Female', 'Transgender'].includes(gender) ? gender : 'Male',
    berth: String(berth || 'No Preference'),
    food: String(food || 'No Food')
  };
  db.passengers.push(p);
  saveDb();
  res.json({ ok: true, passenger: p });
});

app.delete('/api/passengers/:id', requireAuth, (req, res) => {
  const before = db.passengers.length;
  db.passengers = db.passengers.filter(p => !(p.id === req.params.id && p.userId === req.session.user.id));
  saveDb();
  res.json({ ok: true, deleted: before !== db.passengers.length });
});

app.post('/api/passengers/:id/clear-id', requireAuth, (req, res) => {
  let found = false;
  db.passengers.forEach(p => {
    if (p.id === req.params.id && p.userId === req.session.user.id) { p.idType = ''; p.idMasked = ''; found = true; }
  });
  saveDb();
  res.json({ ok: true, cleared: found });
});

app.post('/api/agent/clear-id', requireAgent, (req, res) => {
  const uname = String((req.body || {}).username || '').trim().toLowerCase();
  const u = db.users.find(x => x.username === uname);
  if (!u) return res.status(404).json({ error: 'Customer not found.' });
  u.idType = ''; u.idMasked = ''; u.idNumber = '';
  saveDb();
  res.json({ ok: true });
});

